SET NOCOUNT ON;
SELECT TOP (1) CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion')) AS product_major_version,
 CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductVersion')) AS product_version, CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductLevel')) AS product_level, CONVERT(nvarchar(128),SERVERPROPERTY(N'Edition')) AS edition,
 CONVERT(int,SERVERPROPERTY(N'EngineEdition')) AS engine_edition, CONVERT(nvarchar(256),host.host_platform) AS host_platform, CONVERT(nvarchar(256),host.host_distribution) AS host_distribution, CONVERT(nvarchar(256),host.host_release) AS host_release,
 CONVERT(bit,COALESCE(SERVERPROPERTY(N'IsHadrEnabled'),0)) AS is_hadr_enabled, CONVERT(bit,COALESCE(SERVERPROPERTY(N'IsIntegratedSecurityOnly'),0)) AS is_integrated_security_only, CONVERT(bit,COALESCE(HAS_PERMS_BY_NAME(NULL,NULL,N'VIEW SERVER STATE'),0)) AS has_required_permission, CONVERT(bit,COALESCE(IS_SRVROLEMEMBER(N'##MS_ServerPerformanceStateReader##'),0)) AS is_performance_reader_member, CONVERT(bit,COALESCE(IS_SRVROLEMEMBER(N'sysadmin'),0)) AS is_sysadmin,
 CONVERT(nvarchar(40),CONNECTIONPROPERTY(N'auth_scheme')) AS auth_scheme, CONVERT(nvarchar(40),CONNECTIONPROPERTY(N'net_transport')) AS net_transport, CONVERT(nvarchar(40),connection_info.encrypt_option) AS encrypt_option
FROM sys.dm_os_host_info AS host CROSS JOIN (SELECT TOP (1) current_connection.encrypt_option FROM sys.dm_exec_connections AS current_connection WHERE current_connection.session_id=@@SPID) AS connection_info WHERE CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))=15;
SELECT CONVERT(bit,COALESCE(HAS_PERMS_BY_NAME(N'msdb.dbo.backupset',N'OBJECT',N'SELECT'),0)) AS has_backupset_select, CONVERT(bit,COALESCE(HAS_PERMS_BY_NAME(N'msdb.dbo.sysjobhistory',N'OBJECT',N'SELECT'),0)) AS has_sysjobhistory_select, CONVERT(bit,CASE WHEN CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion')) BETWEEN 15 AND 17 AND CONVERT(int,SERVERPROPERTY(N'EngineEdition')) IN (2,3) THEN 1 ELSE 0 END) AS feature_sql_agent_history;
